def evaluate_credit_score(profile):
    if profile.get('is_unbanked'):
        return {'score': None, 'tier': 'unscored', 'requires_manual_underwriting': True}
    base = 500
    if profile.get('has_default'): base -= 150
    base += min(200, profile.get('ontime_payments_months', 0) * 5)
    return {'score': max(300, min(950, base)), 'tier': 'approved' if base >= 650 else 'rejected'}
